import io,base64,tarfile,os,sys,subprocess,time,json
os.chdir("/kaggle/working"); tarfile.open(fileobj=io.BytesIO(base64.b64decode("")),mode="r:gz").extractall(".")
sys.path.insert(0,"/kaggle/working")
import numpy as np, cupy as cp
from genesis import genome as GN, town, town_xp
print("device", cp.cuda.runtime.getDeviceProperties(0)["name"])
KEYS=["births","survival","balanced","honesty","law_breaks","coop","rep_mean","bond","tools"]
def perm_p(x,y,n=4000,rng=np.random.default_rng(0)):
    x,y=np.asarray(x),np.asarray(y); o=abs(x.mean()-y.mean()); z=np.concatenate([x,y]); c=0
    for _ in range(n): rng.shuffle(z); c+=abs(z[:len(x)].mean()-z[len(x):].mean())>=o
    return (c+1)/(n+1)
res={}
for name,env in [("default",town.default_env()),("cheaters0.1",dict(town.default_env(),cheaters=0.1))]:
    A={k:[] for k in KEYS};B={k:[] for k in KEYS}
    for s in range(24):
        g=GN.sample(np.random.default_rng(1000+s),64)
        a=town.run_town(g,env,s,T=96,per_genome=4); bb=town_xp.run_town(g,env,s,T=96,per_genome=4,xp=cp)
        for k in KEYS: A[k].append(float(np.nanmean(a[k]))); B[k].append(float(np.nanmean(bb[k])))
    for k in KEYS: res[name+"/"+k]=dict(numpy=float(np.mean(A[k])),gpu=float(np.mean(B[k])),p=perm_p(A[k],B[k]))
for k,v in res.items(): print(k, v)
print("p<0.01:", [k for k,v in res.items() if v["p"]<0.01])
# throughput: town of M minds, T=192
for G in (128,1280,10240):
    g=GN.sample(np.random.default_rng(0),G); env=dict(town.default_env(),cheaters=0.1)
    t=time.time(); town_xp.run_town(g,env,1,T=192,per_genome=6,xp=cp); cp.cuda.Stream.null.synchronize(); tg=time.time()-t
    t=time.time(); town_xp.run_town(g,env,1,T=192,per_genome=6,xp=cp); cp.cuda.Stream.null.synchronize(); tg=time.time()-t
    if G<=1280:
        t=time.time(); town.run_town(g,env,1,T=192,per_genome=6); tc=time.time()-t
    else: tc=None
    print(json.dumps(dict(genomes=G,minds=int(G*1.1*6),gpu_s=round(tg,2),cpu1core_s=None if tc is None else round(tc,2))))
json.dump(res,open("gpu_validation.json","w"),indent=1)
